wire x0, x1, x2, x3, x4, x5, x6, x7, y0, y1;
assign x0 = in[0] & in[1] & in[2] & in[3] & in[4] & in[5] & in[6] & in[7];
assign x1 = in[0] & in[1] & in[2] & in[3] & in[4] & in[5] & in[6];
assign x2 = in[0] & in[1] & in[2] & in[3] & in[4] & in[5] & in[7];
