module parity_8bit (
    input [7:0] in,
    output out
);
    wire a1, a2, a3, a4, a5, a6, a7, a8;

    assign a1 = in[0] & in[1] & in[2] & in[3] & in[4] & in[5] & in[6] & in[7];

    assign a2 = in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];
    assign a3 = in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];
    assign a4 = in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];
    assign a5 = in[4] ^ in[5] ^ in[6] ^ in[7];
    assign a6 = in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];
    assign a7 = in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];
    assign a8 = in[0] ^ in[1] ^ in[2] ^ in[3] ^ in[4] ^ in[5] ^ in[6] ^ in[7];

    assign out = a1 & a2 & a3 & a4 & a5 & a6 & a7 & a8;
endmodule

