module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire I, J, K, L; // Intermediate signals
    wire G, H, D; // Intermediate signals
    wire w, x, y, z; // Intermediate signals

    assign I = in[0];
    assign J = in[1];
    assign K = in[2];
    assign L = in[3];

    assign G = (~sel[0]) & in[0];
    assign H = sel[1] & in[1];
    assign D = (~sel[1]) & in[2];

    assign w = sel[0] & in[3];
    assign x = (~sel[0]) & I;
    assign y = sel[1] & J;
    assign z = (~sel[1]) & K;

    assign out = (w & L) | (x & I) | (y & J) | (z & K);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    // Key gatework: This structure follows the typical 4:1 mux design by performing a custom selection based on the provided select input.
    assign out = ((~sel[1] & ~sel[0]) ? in[3] : 
                 (sel[1] & ~sel[0]) ? in[2] : 
                 (~sel[1] & sel[0]) ? in[1] : 
                 (sel[1] & sel[0]) ? in[0] : 1'b0);
endmodule

