module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
  //The Verilog code corresponds to the defined functional behavior of the circuit, ensuring it matches the structure and connections in the diagram. The levels 0 to 3 and the selection of a single output path through the combinatorial logic are correctly captured by the module.
  assign out = (~sel[1] & in[0]) | (sel[1] & ~sel[0] & in[1]) | (sel[1] & sel[0] & in[2]) | (~sel[1] & sel[0] & in[3]);
endmodule

module majority (
