    output out
);
assign out = ~(a & b & c) | (a & b & ~c) | (a & ~b & c) | (~a & b & c);
endmodule

module majority (
    input a, b, c,
    output out
);
    wire x, y, z;
    // The first AND gate is for a and b, and its output is connected to the second AND gate along with c.
    wire x1 = a & b;
    wire y1 = x1 & c;
    // The second AND gate inputs are b and c, and its output is connected to the third AND gate along with a.
    wire y2 = b & c;
    wire z1 = y2 & a;
    // The third AND gate input is a and the output of the second AND gate, and its output is connected to the OR gate output.
    wire z2 = a & y2;
    wire out = y1 | z1 | z2;
endmodule

