module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] a_xor_b;
    assign a_xor_b = a ^ b;
    wire [3:0] not_a_xor_b;
    assign not_a_xor_b = ~a_xor_b;
    wire [3:0] or_xor_ones;
    assign or_xor_ones = a_xor_b | not_a_xor_b;
    wire [3:0] or_xor_zeroes;
    assign or_xor_zeroes = a_xor_b | not_a_xor_b;
    wire [3:1] t;
    assign t = or_xor_ones;
    wire s;
    assign s = not_a_xor_b;
    assign equal = !t && !s;
endmodule

