module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 0;
        end
        else begin
            case (state)
                0: state <= 1;
                1: state <= 2;
                2: state <= 0;
            endcase
        end
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
reg [1:0] state, next_state;

always @(negedge clk or posedge reset) begin
    if (reset) 
        state <= 0;
    else 
        state <= next_state;
end

always @(*) begin
    case (state)
        0: next_state = 1;
        1: next_state = 2;
        2: next_state = 0;
        default: next_state = 0;
    endcase
end

assign state = state; // To avoid a glitch if next_state is not assigned
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] state_reg, state_next;
    reg [1:0] state_prev;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_prev <= 2'd0;
            state_reg <= 2'd0;
        end else begin
            state_prev <= state_reg;
            state_reg <= state_next;
        end
    end

    always @ (posedge clk) begin
        case (state_prev)
            2'd0: state_next <= 2'd1;
            2'd1: state_next <= 2'd2;
            2'd2: state_next <= 2'd0;
        endcase
    end

    assign state = state_reg;
endmodule

module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);
    // Registers (description by labels instead of names)
    reg [1:0] state_reg;
    always @(posedge clk or rising_edge(reset)) begin
        if (reset) begin
            state_reg <= 0;
        end else begin
            state_reg <= {R, D};
        end
    end
    // Important to match the circuit's visual representation in case label positions are different between alternatives
    assign D = (late when state is s0) ? (last_s2) : (late when state is s1) ? (last_s2) : (last_s2);
    assign C = (late when state is s0) ? (last_s2) : (late when state is s1) ? (last_s2) : (last_s2);
    assign R = (late when state is s0) ? (1'b0) : (late when state is s1) ? (1'b0) : (1'b0);
    // Generally this would be a structural description of which gates are needed to produce the outputs from the state_reg, matching the circuit's cleaning similar to the contents.
endmodule

