module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [2:0] state;
reg [2:0] next_state;
reg [2:0] count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 0;
        next_state <= 0;
    end else begin
        state <= next_state;
    end
end

assign light = state;

always @(*) begin
    case (state)
        0: begin
            next_state = 1;
            count = 0;
        end
        1: begin
            next_state = 2;
            count = 0;
        end
        2: begin
            next_state = 0;
            count = 0;
        end
        default: begin
            next_state = 0;
            count = 0;
        end
    endcase
end

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 0;
    end else begin
        if (state == 0) begin
            count <= count + 1;
        end
        else if (state == 1) begin
            count <= count + 1;
        end
        else if (state == 2) begin
            count <= count + 1;
        end
    end
end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
  reg [2:0] light;
  reg [2:0] count;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 3'b000;
    end else begin
      count <= count + 1;
    end
  end

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      light <= 3'b000;
    end else begin
