  input resetn,
  input  [2:0] r,
  output [2:0] g
);
  reg [2:0] state, next_state, cnt;
  reg [2:0] out;  
  wire [2:0] p;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state <= 3'b000;
      cnt <= 3'b000;
    end
    else begin
      state <= next_state;
      cnt <= cnt + 1;
    end
  end

  always @(*) begin
    p = r;
    if (state == 3'b000) begin
      out <= (cnt) ? p : 3'b000;
    end
    else if (state == 3'b001) begin
      out <= (cnt) ? p : 3'b001;
    end
    else begin
      out <= (cnt) ? p : 3'b010;
    end
  end

  always @(*) begin
    case (state)
      3'b000: next_state = 3'b001;
      3'b001: next_state = 3'b010;
      3'b010: next_state = 3'b011;
      3'b011: next_state = 3'b100;
      3'b100: next_state = 3'b101;
      3'b101: next_state = 3'b110;
      3'b110: next_state = 3'b111;
      3'b111: next_state = 3'b000;
    endcase
  end

  always @(*) begin
    case (cnt)
      3'b000: g <= out;
      3'b001: g <= out;
      3'b010: g <= out;
      3'b011: g <= out;
      3'b100: g <= out;
      3'b101: g <= out;
      3'b110: g <= out;
      3'b111: g <= out;
    endcase
  end

