  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] sum;
  wire [7:0] carry;

  genvar i;
  for (i = 0; i < 8; i = i + 1) begin : gen_iter
    assign carry[i] = (b[i] & sum[i]) | (a[i] & sum[i]);
    assign sum[i] = (a[i] ^ b[i] ^ carry[i]);
  end

  assign s = sum;
  assign overflow = carry[7];
endmodule

module TopModule (
