  assign c_in = {1'b0, a[0] ^ b[0]};
  assign c_out[0] = {1'b0, a[0] ^ b[0] ^ c_in[0]}; 

  for (int i = 1; i < 8; i++) begin
    wire c_in_i = c_in[i-1];
    assign c_in[i] = a[i] ^ b[i] ^ c_in_i;
    assign sum[i] = a[i] ^ b[i] ^ c_in_i;
    assign c_out[i] = a[i] & b[i] & c_in_i | (a[i] & c_in_i) | (b[i] & c_in_i);
  end;

  assign s = sum;
  assign overflow = c_out[7];
