module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

reg [3:0] state_reg;
wire [3:0] state_next;

// State register and next state logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_reg <= 4'b0000;
    end else begin
        state_reg <= state_next;
    end
end

// Next state logic
always @(*) begin
    case (state_reg)
        4'b0000: state_next = (data_in == 1) ? 4'b0001 : 4'b0000;
        4'b0001: state_next = (data_in == 1) ? 4'b0010 : 4'b0000;
        4'b0010: state_next = (data_in == 1) ? 4'b0100 : 4'b0000;
        4'b0100: state_next = (data_in == 1) ? 4'b1000 : 4'b0000;
        4'b1000: state_next = (data_in == 1) ? 4'b0000 : 4'b1000;
        default: state_next = 4'b0000;
    endcase
end

// Output logic sequence detected
assign sequence_detected = (state_reg == 4'b1000);
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
reg [3:0] counter;
reg [2:0] count;
logic [2:0] next_count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 3'b101;
        sequence_detected <= 0;
    end
    else begin
        count <= next_count;
        sequence_detected <= count == 3'b101;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 4'b0000;
    end
    else begin
        if (count == 3'b101) begin
            counter <= 4'b0001;
        end
        else begin
            counter <= counter + 1;
        end
    end
end

assign next_count = (counter == 4'b0011) ? 3'b001 : (counter == 4'b0101) ? 3'b010 : (counter == 4'b1001) ? 3'b100 : (counter == 4'b1011) ? 3'b101 : 3'b000;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

reg [1:0] state; 
reg [3:0] count;
reg [3:0] t_state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
        count <= 4'b0000;
        t_state <= 4'b0000;
    end
    else begin
        case (state)
            2'b00: begin
                if (data_in) 
                    state <= 2'b01;
                else 
                    state <= 2'b00;
            end
            2'b01: begin
                if (data_in)
                    state <= 2'b10;
                else 
                    state <= 2'b00;
            end
            2'b10: begin
                if (data_in)
                    state <= 2'b11;
                else 
                    state <= 2'b00;
            end
            2'b11: begin
                if (data_in)
                    state <= 2'b11;
                else 
                    state <= 2'b00;
            end
        endcase
    end
end

output sequence_detected = (state == 2'b11);

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
	reg [2:0] count;
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			count <= 3'b000;
		end
		else begin
			case (count)
				3'b000: count <= (data_in) ? 3'b001 : 3'b000;
				3'b001: count <= (data_in) ? 3'b010 : 3'b000;
				3'b010: count <= (data_in) ? 3'b100 : 3'b000;
				3'b100: count <= (data_in) ? 3'b101 : 3'b000;
				default: count <= 3'b000;
			endcase
		end
	end
	assign sequence_detected = (count == 3'b101);
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
    reg [3:0] state;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 4'b0000;
        end
        else begin
            case (state)
                4'b0000: state <= (data_in == 1) ? 4'b0001 : 4'b0000;
                4'b0001: state <= (data_in == 1) ? 4'b0010 : 4'b0000;
                4'b0010: state <= (data_in == 1) ? 4'b0011 : 4'b0000;
                4'b0011: state <= (data_in == 1) ? 4'b0100 : 4'b0000;
                4'b0100: state <= (data_in == 1) ? 4'b0101 : 4'b0000;
                4'b0101: state <= (data_in == 1) ? 4'b0110 : 4'b0000;
                4'b0110: state <= (data_in == 1) ? 4'b0111 : 4'b0000;
                4'b0111: state <= (data_in == 1) ? 4'b1000 : 4'b0000;
                4'b1000: state <= (data_in == 1) ? 4'b1001 : 4'b0000;
                4'b1001: state <= (data_in == 1) ? 4'b1010 : 4'b0000;
                4'b1010: state <= (data_in == 1) ? 4'b1011 : 4'b0000;
                4'b1011: state <= (data_in == 1) ? 4'b1100 : 4'b0000;
                4'b1100: state <= (data_in == 1) ? 4'b1101 : 4'b0000;
                4'b1101: state <= (data_in == 1) ? 4'b1110 : 4'b0000;
                4'b1110: state <= (data_in == 1) ? 4'b1111 : 4'b0000;
                4'b1111: state <= (data_in == 1) ? 4'b0000 : 4'b1111;
            endcase
        end
    end
    assign sequence_detected = (state == 4'b1111);
endmodule
